SELECT ROUND(
    MAX(
        CAST((et.type_indices->>'safety_idx') AS numeric) / 100.0 * 
        CAST(((et.type_indices->>'performance_score')::real + e."RELIAB_IDX") / 2.0 AS numeric) * 
        (1.0 - CAST(et.type_indices->>'environmental_impact_idx' AS numeric) / 100.0) * 0.8
    ) as numeric, 4
) as max_vehicle_ospi
FROM "Equipment" e 
JOIN "EquipmentType" et ON e."EquipType" = et."EquipType"
WHERE e."EquipType" = 'Vehicle';

